parameters.jsCode:
// INPUT:
// {{getDate.departureType}}  => 'single' or 'range'
// {{getDate.departureDate}} => starting date
// {{getDate.departureEndDate}} => optional, only if range
// {{getDate.returnDate}} => can be null

function parseDate(input) {
  const date = new Date(input);
  if (!isNaN(date.getTime())) {
    return date.toISOString().split('T')[0];
  }
  return null;
}

const departureType = $('AI Agent').first().json.output.departureType;
const departureStart = parseDate($('AI Agent').first().json.output.departureDate);
const departureEnd = $('AI Agent').first().json.output.departureEndDate ? parseDate($('AI Agent').first().json.output.departureEndDate) : null;
const returnDate = parseDate($('AI Agent').first().json.output.returnDate);

let output = [];

if (departureType === 'single') {
  // Just one date
  output.push({
    departureDate: departureStart,
    returnDate: returnDate
  });
} else if (departureType === 'range' && departureStart && departureEnd) {
  // Range of dates (e.g. next week)
  const start = new Date(departureStart);
  const end = new Date(departureEnd);
  for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
    output.push({
      departureDate: d.toISOString().split('T')[0],
      returnDate: returnDate
    });
  }
}

return output;

// Merge data
result = [];
for (const item of $input.all()) {
  result = result.concat(JSON.parse(item.json.data).data);
}

// Extract fields
final_result = [];
for (x of result) {
  let legs = x.itineraries[0].segments.map(y => {
    let a = $('CarrierNameLookup').item.json[y.carrierCode];
    let carrier = a.name ? a.name : a.icao;
    return { carrier: carrier, duration: y.duration };
  });

  let time = x.itineraries[0].segments[0].departure.at;
  let duration = x.itineraries[0].duration;
  let price = x.price.total + ' ' + x.price.currency;

  // Try to extract booking link
  let bookingLink = null;

  // Option 1: Common pattern
  if (x.links && x.links.booking) {
    bookingLink = x.links.booking;
  }

  // Option 2: Alternative pattern
  else if (x.offerUrl) {
    bookingLink = x.offerUrl;
  }

  // Add flight info to result
  final_result.push({
    legs: legs,
    time: time,
    duration: duration,
    price: price,
    //link: bookingLink // include the booking link
  });
}

return final_result;

var carrierCodes={}
JSON.parse($('Get Carrier Codes').first().json.data).data.forEach(datum=>{
  carrierCodes[datum.iataCode] = {icao:datum.icaoCode, name:datum.commonName}
})
return carrierCodes

